import java.nio.file.*;import java.util.*;import java.util.zip.*;import java.nio.charset.StandardCharsets;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes{
static String helper="dev/zomboid/lang/Localized";
static void load(InsnList x,Type t,int local){x.add(new VarInsnNode(t.getOpcode(ILOAD),local));String owner=null,desc=null;switch(t.getSort()){case Type.BOOLEAN:owner="Boolean";desc="Z";break;case Type.BYTE:owner="Byte";desc="B";break;case Type.CHAR:owner="Character";desc="C";break;case Type.SHORT:owner="Short";desc="S";break;case Type.INT:owner="Integer";desc="I";break;case Type.FLOAT:owner="Float";desc="F";break;case Type.LONG:owner="Long";desc="J";break;case Type.DOUBLE:owner="Double";desc="D";break;}if(owner!=null)x.add(new MethodInsnNode(INVOKESTATIC,"java/lang/"+owner,"valueOf","("+desc+")Ljava/lang/"+owner+";",false));}
public static void main(String[]a)throws Exception{Map<String,String> keys=new HashMap<>();for(String line:Files.readAllLines(Path.of(a[2]))){String[]p=line.split("\t");keys.put(new String(Base64.getDecoder().decode(p[0]),StandardCharsets.UTF_8),p[1]);}int literals=0,recipes=0,zones=0;Set<String> used=new TreeSet<>();try(ZipFile z=new ZipFile(a[0]);ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var es=z.entries();es.hasMoreElements();){var e=es.nextElement();byte[] data=z.getInputStream(e).readAllBytes();if(e.getName().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(data).accept(c,0);boolean changed=false;for(var m:c.methods){if(m.name.equals("<clinit>"))continue;for(var n:m.instructions.toArray()){
if(n instanceof MethodInsnNode f&&f.getOpcode()==INVOKESTATIC&&f.owner.equals("net/minecraft/network/chat/Component")&&f.name.equals("literal")){f.owner=helper;f.name="component";f.itf=false;changed=true;}
if(n instanceof LdcInsnNode l&&l.cst instanceof String s&&keys.containsKey(s)){InsnList x=new InsnList();x.add(new LdcInsnNode(keys.get(s)));x.add(new MethodInsnNode(INVOKESTATIC,helper,"text","(Ljava/lang/String;Ljava/lang/String;)Ljava/lang/String;",false));m.instructions.insert(n,x);used.add(s);literals++;changed=true;}
if(n instanceof FieldInsnNode f&&f.getOpcode()==GETSTATIC&&f.owner.equals("dev/survivorcreator/spawn/Zones")&&f.desc.equals("[Ljava/lang/String;")){var next=n.getNext();int budget=12;while(next!=null&&budget-->0&&next.getOpcode()!=AALOAD&&next.getOpcode()!=ARRAYLENGTH)next=next.getNext();if(next==null||next.getOpcode()!=AALOAD)continue;m.instructions.insert(next,new MethodInsnNode(INVOKESTATIC,helper,"raw","(Ljava/lang/String;)Ljava/lang/String;",false));zones++;changed=true;}
if(n instanceof InvokeDynamicInsnNode d&&d.bsm.getOwner().equals("java/lang/invoke/StringConcatFactory")&&d.bsmArgs.length==1&&d.bsmArgs[0] instanceof String recipe&&keys.containsKey(recipe)){
Type[]ts=Type.getArgumentTypes(d.desc);int[]locals=new int[ts.length];for(int i=0;i<ts.length;i++){locals[i]=m.maxLocals;m.maxLocals+=ts[i].getSize();}InsnList x=new InsnList();for(int i=ts.length-1;i>=0;i--)x.add(new VarInsnNode(ts[i].getOpcode(ISTORE),locals[i]));x.add(new LdcInsnNode(keys.get(recipe)));x.add(new LdcInsnNode(recipe.replace("%","%%").replace("\1","%s")));x.add(new LdcInsnNode(ts.length));x.add(new TypeInsnNode(ANEWARRAY,"java/lang/Object"));for(int i=0;i<ts.length;i++){x.add(new InsnNode(DUP));x.add(new LdcInsnNode(i));load(x,ts[i],locals[i]);x.add(new InsnNode(AASTORE));}x.add(new MethodInsnNode(INVOKESTATIC,helper,"concat","(Ljava/lang/String;Ljava/lang/String;[Ljava/lang/Object;)Ljava/lang/String;",false));m.instructions.insertBefore(n,x);m.instructions.remove(n);used.add(recipe);recipes++;changed=true;}
}}
if(changed){ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);data=w.toByteArray();ClassNode check=new ClassNode();new ClassReader(data).accept(check,0);for(var m:check.methods)if(m.instructions.size()>0)new Analyzer<>(new BasicVerifier()).analyze(check.name,m);System.out.println("Patched "+c.name);}}
out.putNextEntry(new ZipEntry(e.getName()));out.write(data);out.closeEntry();}}System.out.println("Localized "+literals+" literals, "+recipes+" concat templates and "+zones+" zone lookups");Files.writeString(Path.of(a[3]),String.join("\n",used));}}
